import { getAccount } from './controllers/accounts.js';

export function createApp({ accounts, auditEvents }) {
  return {
    async request(method, pathname) {
      const match = pathname.match(/^\/accounts\/([^/]+)$/);
      if (method === 'GET' && match) {
        const account = getAccount(accounts, match[1]);
        return { status: account ? 200 : 404, body: account };
      }
      return { status: 404, body: null };
    },
    stores: { accounts, auditEvents }
  };
}

--- src/controllers/accounts.js ---
import { findAccount } from '../services/account-service.js';

export function getAccount(records, id) {
  return findAccount(records, id);
}

--- src/models/account.js ---
import { ACCOUNT_STATES } from '../services/account-service.js';

export function materializeAccount(row) {
  return { ...row, state: row.state || ACCOUNT_STATES.active };
}

--- src/services/account-service.js ---
import { materializeAccount } from '../models/account.js';

export const ACCOUNT_STATES = Object.freeze({ active: 'active', suspended: 'suspended' });

export function findAccount(records, id) {
  const row = records.find((account) => account.id === id);
  return row ? materializeAccount(row) : null;
}

--- src/services/audit.js ---
export function appendAudit(events, event) {
  events.push({ ...event });
}

--- test/app.test.js ---
import test from 'node:test';
import assert from 'node:assert/strict';
import { createApp } from '../src/app.js';

test('reads an existing account', async () => {
  const app = createApp({ accounts: [{ id: 'a1', name: 'Ada' }], auditEvents: [] });
  const response = await app.request('GET', '/accounts/a1');
  assert.equal(response.status, 200);
  assert.equal(response.body.state, 'active');
});

